import React, { useState } from 'react';
import MessagesList from './MessagesList';
import ChatWindow from './ChatWindow';

const MessagesPage = ({ currentUser }) => {
  const [selectedUser, setSelectedUser] = useState(null);

  return (
    <div className="messages-page" style={{ display: 'flex' }}>
      <div className="sidebar" style={{ width: '30%' }}>
        <MessagesList currentUser={currentUser} onSelectUser={setSelectedUser} />
      </div>
      <div className="chat-area" style={{ width: '70%' }}>
        {selectedUser ? (
          <ChatWindow currentUser={currentUser} selectedUser={selectedUser} />
        ) : (
          <p>Select a user to start chatting</p>
        )}
      </div>
    </div>
  );
};

export default MessagesPage;
